sqlMap.insert:
 insert into program_total_seats_allocation
SELECT #program_id#,#seats#,#newSeats#,num_seat,gn,bc,sc,st FROM seats_allocation where num_seat >#newSeats#
order by num_seat limit 1;

sqlMap.select:
select set1.marks from
(
select * from jee_marks where #marksObtained# between min2 and max2 limit 1)set1;





select application_number ,interview,cca,class as class1 from marks_entry_panel
where  Present_status ='P' and update_flag ='N'
and class in ('certificate_agra','certificate')   ;

sqlMap.update:
update marks_entry_panel mep join ( select set1.application_number,set1.program_id,sfm.marks from ( select sas.application_number , stn.registration_number,stn.program_id,stn.entity_id from student_application_status sas join student_test_number stn on sas.application_number=stn.test_number
where sas.binded_application_number in ( select binded_application_number from student_application_status where application_number in(#application_number#) )and stn.called in ('Y','N'))set1
join student_final_marks sfm on sfm.registration_number=set1.registration_number where sfm.evaluation_component in ('PW') and attended='P')set2 on mep.application_number =set2.application_number and mep.class =set2.program_id and set2.marks != mep.interview and set2.marks > mep.interview set mep.INT_OLD =mep.interview, mep.interview=set2.marks,mep.update_flag='N',mep.Present_status='P', mep.modification_time=now();

update marks_entry_panel mep join ( select set1.application_number,set1.program_id,sfm.marks from ( select sas.application_number , stn.registration_number,stn.program_id,stn.entity_id from student_application_status sas join student_test_number stn on sas.application_number=stn.test_number
where sas.binded_application_number in ( select binded_application_number from student_application_status where application_number in(#application_number#) )and stn.called in ('Y','N'))set1
join student_final_marks sfm on sfm.registration_number=set1.registration_number where sfm.evaluation_component in ('CA') and attended='P')set2 on mep.application_number =set2.application_number and mep.class =set2.program_id and set2.marks != mep.CCA and set2.marks > mep.CCA set mep.CCA_OLD =mep.CCA, mep.CCA=set2.marks,mep.update_flag='N',mep.Present_status='P', mep.modification_time=now();

